# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: shape
def shape(xs):
    return [v * v for v in xs]

# region: render
def render(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: gather
def gather(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(digest(gather(render(shape(intake(raw))))))

